```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Denial</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0;
            padding: 0;
            height: 100vh;
            background: #f0f0f0;
            border: 2px solid #ddd;
        }
        header {
            background: white;
            padding: 20px;
            color: #333;
            text-align: center;
        }
        .denial {
            text-align: center;
        }
        .disabled {
            text-align: center;
        }
    </style>
</head>
<body>
    <header>
        <h1>THIS IS A DENIAL</h1>
        <p>Access Denied</p>
        <div id="status">DENIAL</div>
    </header>

    <div id="status" class="denial">
        <h3>Status</h3>
        <p>Insufficient payment or verification</p>
    </div>
